function divisibleSlices(nums: number[], k: number): number {
  const count = new Array(k).fill(0);
  count[0] = 1; // empty prefix
  let rem = 0, total = 0;
  for (const x of nums) {
    rem = (((rem + x) % k) + k) % k;
    total += count[rem];
    count[rem]++;
  }
  return total;
}

